def get_best_schedule(workload, num_seqs):
    """
    Conflict-graph decomposition + exact DP + iterated local search.

    1. Build key->transaction incidence; free txns (sharing no key)
       add no conflict cost and are reinserted greedily later.
    2. Split conflict graph into connected components (union-find);
       components are independent and scheduled separately.
    3. Components <= 12 txns solved exactly via Held-Karp bitmask DP
       using the true cost function.
    4. Larger components: multi-restart greedy + local search.
    5. Full-sequence polish + ILS with remaining time budget.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns

    def txn_keys(t):
        for attr in ("txns", "transactions", "txn_list"):
            data = getattr(workload, attr, None)
            if data is None:
                continue
            item = data[t] if isinstance(data, (list, tuple)) else data.get("txn%d" % t)
            if item is None and isinstance(data, dict):
                for k in (t, str(t), "txn%d" % t):
                    if k in data:
                        item = data[k]
                        break
            if item is None:
                continue
            keys = set()
            if isinstance(item, str):
                toks = item.split()
            elif isinstance(item, (list, tuple)):
                toks = [str(x) for x in item]
            else:
                toks = []
            for tok in toks:
                parts = tok.split("-")
                if len(parts) == 2:
                    keys.add(parts[1])
            if keys or toks:
                return keys
        return set()

    keys_of = {}
    key_map = {}
    for t in range(n):
        ks = txn_keys(t)
        keys_of[t] = ks
        for k in ks:
            key_map.setdefault(k, set()).add(t)

    free_txns = [t for t in range(n)
                 if all(len(key_map[k]) == 1 for k in keys_of[t])]
    free_set = set(free_txns)
    core = [t for t in range(n) if t not in free_set]

    # union-find for connected components
    parent = {t: t for t in core}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for k, ts in key_map.items():
        ts = [x for x in ts if x not in free_set]
        for i in range(1, len(ts)):
            a, b = find(ts[0]), find(ts[i])
            if a != b:
                parent[a] = b
    groups = {}
    for t in core:
        groups.setdefault(find(t), []).append(t)
    components = [sorted(g) for g in groups.values()]
    components.sort(key=len)

    def exact_dp(comp, deadline):
        m = len(comp)
        if m > 12:
            return None
        full = (1 << m) - 1
        dp = {0: (0, [])}
        order_masks = sorted(range(1, full + 1), key=lambda x: bin(x).count("1"))
        for mask in order_masks:
            if time.time() - start_time > deadline:
                return None
            best = None
            for i in range(m):
                bit = 1 << i
                if not (mask & bit):
                    continue
                prev = mask ^ bit
                if prev not in dp:
                    continue
                pc, porder = dp[prev]
                seq = porder + [comp[i]]
                c = workload.get_opt_seq_cost(seq)
                if best is None or c < best[0]:
                    best = (c, seq)
            if best is not None:
                dp[mask] = best
        return dp.get(full)

    def greedy_comp(comp, start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in comp if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
                c = workload.get_opt_seq_cost(seq + [t])
                scored.append((c, random.random() if noise else t, t))
            scored.sort()
            pick = scored[0][2]
            if noise and len(scored) > 1 and random.random() < noise:
